from collections import Counter

def bpe(words, n_merges):
    # words: {단어: 빈도}. 각 단어를 문자 튜플로 시작
    corpus = {tuple(w): c for w, c in words.items()}
    merges = []
    for _ in range(n_merges):
        pairs = Counter()
        for toks, c in corpus.items():
            for a, b in zip(toks, toks[1:]):
                pairs[(a, b)] += c
        if not pairs:
            break
        best = max(pairs, key=pairs.get)      # 탐욕: 가장 잦은 쌍
        merges.append(best)
        new = {}
        for toks, c in corpus.items():
            out, i = [], 0
            while i < len(toks):
                if i + 1 < len(toks) and (toks[i], toks[i+1]) == best:
                    out.append(toks[i] + toks[i+1]); i += 2
                else:
                    out.append(toks[i]); i += 1
            new[tuple(out)] = c
        corpus = new
    return merges, corpus

print(bpe({'low': 3, 'lower': 1, 'lowest': 1}, 3))

import torch

@torch.no_grad()
def generate(model, prompt_ids, max_new, eos_id, bos_id=0):
    ids = [bos_id] + list(prompt_ids)           # x0, x1..xk
    for _ in range(max_new):
        x = torch.tensor(ids)[None]             # (1, t)
        logits = model(x)[0, -1]                # 마지막 위치의 u — (|V|,)
        probs = torch.softmax(logits, dim=-1)
        nxt = torch.multinomial(probs, 1).item()  # 분포에서 샘플링
        ids.append(nxt)                         # 출력을 다시 입력으로
        if nxt == eos_id:
            break
    return ids[1 + len(prompt_ids):]

import torch

def sample(logits, tau=1.0, top_k=None):
    if tau == 0:                                  # 탐욕 디코딩
        return int(logits.argmax())
    z = logits / tau
    if top_k is not None:
        kth = torch.topk(z, top_k).values[-1]     # k번째로 큰 값
        z = z.masked_fill(z < kth, float('-inf')) # 나머지 제거
    p = torch.softmax(z, dim=-1)                  # 재정규화 포함
    return int(torch.multinomial(p, 1))

