import torch, torch.nn as nn

class MLP(nn.Module):
    def __init__(self, d, hidden):
        super().__init__()
        self.net = nn.Sequential(nn.Linear(d, hidden), nn.GELU(), nn.Linear(hidden, d))
    def forward(self, h):            # h: (T, d) — 마지막 축에만 작용
        return self.net(h)

class TinyLM(nn.Module):
    def __init__(self, V, d, n_layers, attn_factory):
        super().__init__()
        self.emb = nn.Embedding(V, d)
        self.attn = nn.ModuleList([attn_factory() for _ in range(n_layers)])
        self.mlp = nn.ModuleList([MLP(d, 4 * d) for _ in range(n_layers)])
        self.out = nn.Linear(d, V)
    def forward(self, x):            # x: (T,) 토큰 ID
        h = self.emb(x)
        for a, m in zip(self.attn, self.mlp):
            h = m(a(h))              # 위치 섞기 → 위치별 처리
        return self.out(h)           # (T, |V|) 로짓

def mlp_concat_params(T, d):
    return (T * d) ** 2            # 첫 층 하나만

def attn_params(d, d_h):
    return 3 * d * d_h             # T 와 무관

for T in [1_000, 1_001, 1_000_000]:
    print(T, f'{mlp_concat_params(T, 1024):.2e}', attn_params(1024, 1024))
